from collections import deque

def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]==0 and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));
    for x,y in q:
     for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
      if 0<=a<h and 0<=b<w and g[a][b]==0 and (a,b) not in seen: seen.add((a,b));q.append((a,b))
    out.append(q)
 return out
